      y = (@mt[kk] & UPPER_MASK) | (@mt[(kk + 1) % N] & LOWER_MASK)
      @mt[kk] = @mt[(kk + M) % N] ^ (y >> 1) ^ (if y.odd?
        MATRIX_A
